contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amt)); require(amt <= 1000000000000000000000000000000);
        uint256 beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        c.Deposit{value: amt}(); if (__ESBMC_reverted()) return;

        uint256 afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        assert(afterBal == beforeBal + amt);
    }

    receive() external payable {}
}

